using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.Json;

namespace BattlefieldFrontlineCollector;

/// <summary>Small built-in UI dictionary; capture files remain language-neutral.</summary>
internal static class I18n
{
    public static readonly string[] Codes = ["auto", "zh-CN", "zh-TW", "en", "ja", "de", "fr", "th", "vi"];
    public static readonly string[] Names = ["自動 / Auto", "简体中文", "繁體中文", "English", "日本語", "Deutsch", "Français", "ไทย", "Tiếng Việt"];
    private static IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> Extended =
        new Dictionary<string, IReadOnlyDictionary<string, string>>();

    public static void Configure(string assetRoot)
    {
        foreach (var directory in new[] { "assets", "Assets" })
        {
            var path = Path.Combine(assetRoot, directory, "localization", "ui_extended.json");
            if (!File.Exists(path)) continue;
            try
            {
                using var document = JsonDocument.Parse(File.ReadAllText(path));
                var result = new Dictionary<string, IReadOnlyDictionary<string, string>>(StringComparer.Ordinal);
                foreach (var entry in document.RootElement.GetProperty("translations").EnumerateObject())
                {
                    var values = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
                    foreach (var value in entry.Value.EnumerateObject())
                        if (!string.IsNullOrWhiteSpace(value.Value.GetString())) values[value.Name] = value.Value.GetString()!;
                    result[entry.Name] = values;
                }
                Extended = result;
                return;
            }
            catch { return; }
        }
    }

