    public static string Get(string configuredCode, string key)
    {
        if (!Text.TryGetValue(key, out var values)) return key;
        var code = configuredCode == "auto" ? CultureInfo.CurrentUICulture.Name : configuredCode;
        var normalized = code.StartsWith("de", StringComparison.OrdinalIgnoreCase) ? "de"
            : code.StartsWith("fr", StringComparison.OrdinalIgnoreCase) ? "fr"
            : code.StartsWith("th", StringComparison.OrdinalIgnoreCase) ? "th"
            : code.StartsWith("vi", StringComparison.OrdinalIgnoreCase) ? "vi" : string.Empty;
        if (normalized.Length > 0 && Extended.TryGetValue(key, out var translated) &&
            translated.TryGetValue(normalized, out var extended) && !string.IsNullOrWhiteSpace(extended))
            return extended;
        var index = code.StartsWith("zh-TW", StringComparison.OrdinalIgnoreCase) ||
                    code.StartsWith("zh-HK", StringComparison.OrdinalIgnoreCase) ? 1
            : code.StartsWith("zh", StringComparison.OrdinalIgnoreCase) ? 0
            : code.StartsWith("ja", StringComparison.OrdinalIgnoreCase) ? 3 : 2;
        return values[index];
    }
}
